// ============================================================
// Altamira Capital - Weekly Metrics Calculator
// ============================================================
// Reads Daily Dashboard and Trade Log data for the past week,
// calculates weekly and cumulative performance metrics.
// ============================================================

// -----------------------------------------------------------
// Collect inputs from both Google Sheets reads
// -----------------------------------------------------------
const allItems = $input.all();

// The items come merged from both branches.
// We need to separate daily dashboard rows from trade log rows.
// We'll use the presence of 'Portfolio Value' field to identify dashboard rows
// and 'Trade ID' field to identify trade log rows.
const dailyRows = [];
const tradeRows = [];

for (const item of allItems) {
  const data = item.json;
  if (data['Portfolio Value'] !== undefined || data['portfolioValue'] !== undefined) {
    dailyRows.push(data);
  }
  if (data['Trade ID'] !== undefined || data['tradeId'] !== undefined) {
    tradeRows.push(data);
  }
}

// -----------------------------------------------------------
// Date calculations
// -----------------------------------------------------------
const now = new Date();
const weekEnd = new Date(now);
weekEnd.setDate(now.getDate() - now.getDay()); // Sunday
const weekStart = new Date(weekEnd);
weekStart.setDate(weekEnd.getDate() - 7); // Previous Sunday

const weekStartStr = weekStart.toISOString().split('T')[0];
const weekEndStr = weekEnd.toISOString().split('T')[0];

function parseDate(dateStr) {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  return isNaN(d.getTime()) ? null : d;
}

function isInWeek(dateStr) {
  const d = parseDate(dateStr);
  if (!d) return false;
  return d >= weekStart && d <= weekEnd;
}

// -----------------------------------------------------------
// Filter this week's daily data
// -----------------------------------------------------------
const thisWeekDaily = dailyRows.filter(row => {
  const dateField = row['Date'] || row['date'];
  return isInWeek(dateField);
});

// -----------------------------------------------------------
// Filter this week's trades
// -----------------------------------------------------------
const thisWeekTradesOpened = tradeRows.filter(row => {
  const dateField = row['Date (Entry)'] || row['dateEntry'];
  return isInWeek(dateField);
});

const thisWeekTradesClosed = tradeRows.filter(row => {
  const dateField = row['Date (Exit)'] || row['dateExit'];
  return isInWeek(dateField);
});

// -----------------------------------------------------------
// Weekly P&L
// -----------------------------------------------------------
let weeklyPnL = 0;
let weeklyPnLPercent = 0;
let startingPortfolioValue = 100000;
let endingPortfolioValue = 100000;

if (thisWeekDaily.length > 0) {
  // Sort by date
  thisWeekDaily.sort((a, b) => {
    const da = new Date(a['Date'] || a['date']);
    const db = new Date(b['Date'] || b['date']);
    return da - db;
  });

  const firstDay = thisWeekDaily[0];
  const lastDay = thisWeekDaily[thisWeekDaily.length - 1];

  startingPortfolioValue = parseFloat(firstDay['Portfolio Value'] || firstDay['portfolioValue'] || 100000);
  endingPortfolioValue = parseFloat(lastDay['Portfolio Value'] || lastDay['portfolioValue'] || 100000);

  // If we have previous week data, use the day before the first entry
  // For now, use the first day's value as start
  weeklyPnL = endingPortfolioValue - startingPortfolioValue;
  weeklyPnLPercent = startingPortfolioValue > 0 ? (weeklyPnL / startingPortfolioValue * 100) : 0;
}

// -----------------------------------------------------------
// Win Rate (cumulative from all closed trades)
// -----------------------------------------------------------
const allClosedTrades = tradeRows.filter(row => {
  const exitDate = row['Date (Exit)'] || row['dateExit'];
  const exitPrice = row['Exit Price'] || row['exitPrice'];
  return exitDate && exitPrice !== '' && exitPrice !== undefined;
});

let totalWins = 0;
let totalLosses = 0;

for (const trade of allClosedTrades) {
  const rawPnL = parseFloat(trade['Raw P&L'] || trade['rawPnL'] || trade['Adjusted P&L'] || trade['adjustedPnL'] || 0);
  if (rawPnL > 0) {
    totalWins++;
  } else if (rawPnL < 0) {
    totalLosses++;
  } else {
    // Breakeven - count as win
    totalWins++;
  }
}

const totalClosedCount = totalWins + totalLosses;
const winRate = totalClosedCount > 0 ? (totalWins / totalClosedCount * 100) : 0;

// -----------------------------------------------------------
// Rolling Sharpe Ratio (annualized from weekly returns)
// -----------------------------------------------------------
// Calculate weekly returns from all daily dashboard data
const RISK_FREE_WEEKLY = 0.000847; // (1 + 0.045)^(1/52) - 1

// Group daily rows by week
const weeklyReturns = [];
const sortedDaily = [...dailyRows].sort((a, b) => {
  return new Date(a['Date'] || a['date']) - new Date(b['Date'] || b['date']);
});

// Simple approach: calculate return for each 5-trading-day block
let weekBlocks = [];
let currentBlock = [];
for (const row of sortedDaily) {
  currentBlock.push(row);
  if (currentBlock.length >= 5) {
    weekBlocks.push([...currentBlock]);
    currentBlock = [];
  }
}
if (currentBlock.length > 0) weekBlocks.push(currentBlock);

for (const block of weekBlocks) {
  if (block.length >= 2) {
    const startVal = parseFloat(block[0]['Portfolio Value'] || block[0]['portfolioValue'] || 100000);
    const endVal = parseFloat(block[block.length - 1]['Portfolio Value'] || block[block.length - 1]['portfolioValue'] || 100000);
    if (startVal > 0) {
      weeklyReturns.push((endVal - startVal) / startVal);
    }
  }
}

let rollingSharpe = 'Need 4+ weeks';
if (weeklyReturns.length >= 4) {
  const mean = weeklyReturns.reduce((a, b) => a + b, 0) / weeklyReturns.length;
  const variance = weeklyReturns.reduce((sum, r) => sum + Math.pow(r - mean, 2), 0) / (weeklyReturns.length - 1);
  const stdDev = Math.sqrt(variance);
  if (stdDev > 0) {
    rollingSharpe = ((mean - RISK_FREE_WEEKLY) / stdDev * Math.sqrt(52)).toFixed(2);
  } else {
    rollingSharpe = 'N/A (zero variance)';
  }
}

// -----------------------------------------------------------
// Max Drawdown (cumulative)
// -----------------------------------------------------------
let maxDrawdown = 0;
let peakValue = 0;

for (const row of sortedDaily) {
  const val = parseFloat(row['Portfolio Value'] || row['portfolioValue'] || 100000);
  if (val > peakValue) peakValue = val;
  if (peakValue > 0) {
    const drawdown = (val - peakValue) / peakValue;
    if (drawdown < maxDrawdown) maxDrawdown = drawdown;
  }
}

const maxDrawdownPercent = (maxDrawdown * 100).toFixed(2);

// -----------------------------------------------------------
// Rule Compliance (count violations)
// -----------------------------------------------------------
const ruleViolations = tradeRows.filter(row => {
  const compliance = (row['Rule Compliance'] || row['ruleCompliance'] || 'Yes').toString().toLowerCase();
  return compliance === 'no' || compliance === 'false';
}).length;

// -----------------------------------------------------------
// Weekly trades summary
// -----------------------------------------------------------
const tradesOpenedCount = thisWeekTradesOpened.length;
const tradesClosedCount = thisWeekTradesClosed.length;

let weekWins = 0;
let weekLosses = 0;
for (const trade of thisWeekTradesClosed) {
  const pnl = parseFloat(trade['Raw P&L'] || trade['rawPnL'] || trade['Adjusted P&L'] || trade['adjustedPnL'] || 0);
  if (pnl >= 0) weekWins++;
  else weekLosses++;
}

// -----------------------------------------------------------
// Build output
// -----------------------------------------------------------
const weeklyPassFail = {
  winRate: winRate >= 60 ? 'PASS' : (winRate > 0 ? 'WATCH' : 'N/A'),
  sharpe: typeof rollingSharpe === 'number' || !isNaN(parseFloat(rollingSharpe)) ? (parseFloat(rollingSharpe) >= 1.0 ? 'PASS' : 'FAIL') : 'PENDING',
  maxDrawdown: parseFloat(maxDrawdownPercent) > -10 ? 'PASS' : 'FAIL',
  weeklyLoss: weeklyPnLPercent >= -3 ? 'PASS' : 'FAIL',
  ruleCompliance: ruleViolations === 0 ? 'PASS' : 'FAIL'
};

const output = {
  weekOf: weekStartStr,
  weekEnd: weekEndStr,
  weeklyPnL: Math.round(weeklyPnL * 100) / 100,
  weeklyPnLPercent: Math.round(weeklyPnLPercent * 100) / 100,
  startingValue: Math.round(startingPortfolioValue * 100) / 100,
  endingValue: Math.round(endingPortfolioValue * 100) / 100,
  tradesOpened: tradesOpenedCount,
  tradesClosed: tradesClosedCount,
  weekWins: weekWins,
  weekLosses: weekLosses,
  cumulativeWinRate: Math.round(winRate * 100) / 100,
  rollingSharpe: rollingSharpe,
  maxDrawdown: maxDrawdownPercent,
  ruleViolations: ruleViolations,
  totalClosedTrades: totalClosedCount,
  totalWins: totalWins,
  totalLosses: totalLosses,
  passFailChecks: weeklyPassFail
};

// -----------------------------------------------------------
// Build Telegram message
// -----------------------------------------------------------
const pnlSign = weeklyPnL >= 0 ? '+' : '';
const sharpeDisplay = typeof rollingSharpe === 'string' ? rollingSharpe : rollingSharpe;

const telegramMsg = `ALTAMIRA CAPITAL - Weekly Report\n` +
  `Week: ${weekStartStr} to ${weekEndStr}\n` +
  `===========================================\n` +
  `\nPERFORMANCE\n` +
  `Weekly P&L: ${pnlSign}$${weeklyPnL.toFixed(2)} (${pnlSign}${weeklyPnLPercent.toFixed(2)}%) ${weeklyPassFail.weeklyLoss}\n` +
  `Portfolio: $${startingPortfolioValue.toFixed(2)} -> $${endingPortfolioValue.toFixed(2)}\n` +
  `\nTRADES\n` +
  `Opened: ${tradesOpenedCount} | Closed: ${tradesClosedCount}\n` +
  `This Week: ${weekWins}W / ${weekLosses}L\n` +
  `\nCUMULATIVE METRICS\n` +
  `Win Rate: ${winRate.toFixed(1)}% (${totalWins}W/${totalLosses}L of ${totalClosedCount} closed) ${weeklyPassFail.winRate}\n` +
  `Rolling Sharpe: ${sharpeDisplay} ${weeklyPassFail.sharpe}\n` +
  `Max Drawdown: ${maxDrawdownPercent}% ${weeklyPassFail.maxDrawdown}\n` +
  `Rule Violations: ${ruleViolations} ${weeklyPassFail.ruleCompliance}\n` +
  `\n===========================================\n` +
  `GO-LIVE SCORECARD\n` +
  `Win Rate >= 60%: ${weeklyPassFail.winRate}\n` +
  `Sharpe >= 1.0: ${weeklyPassFail.sharpe}\n` +
  `Max DD > -10%: ${weeklyPassFail.maxDrawdown}\n` +
  `Weekly Loss > -3%: ${weeklyPassFail.weeklyLoss}\n` +
  `Rule Compliance 100%: ${weeklyPassFail.ruleCompliance}\n` +
  `===========================================`;

output.telegramMessage = telegramMsg;

return [{ json: output }];
